import pytest

if pytest.use_correct:
    from correct_python_programs.bucketsort import bucketsort
else:
    from python_programs.bucketsort import bucketsort


def test_attack_1():
    # k much larger than n, values >= n: kills enumerate(arr) and range(len(arr)) variants
    assert bucketsort([5, 2], 10) == [2, 5]


def test_attack_2():
    # k much smaller than n with duplicates
    assert bucketsort([1, 1, 1, 1, 0, 1], 2) == [0, 1, 1, 1, 1, 1]


def test_attack_3():
    # k == n permutation: enumerate(arr) gives wrong multiplicities
    assert bucketsort([2, 0, 1], 3) == [0, 1, 2]


def test_attack_4():
    # all same value, k == 1, n > k
    assert bucketsort([0, 0, 0], 1) == [0, 0, 0]


def test_attack_5():
    # empty input with k > 0 and k == 0
    assert bucketsort([], 5) == []
    assert bucketsort([], 0) == []


def test_attack_6():
    # mixed values with gaps and duplicates, k > n
    assert bucketsort([4, 0, 2, 4, 0, 3], 5) == [0, 0, 2, 3, 4, 4]


def test_attack_7():
    # single element with large k
    assert bucketsort([7], 8) == [7]
